Here's a standalone HTML stopwatch with start, pause, and reset controls. It uses timestamp-based timing so the display stays accurate even when callbacks are delayed.
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Stopwatch</title>
<style>
  :root {
    color-scheme: dark;
    --bg: #0f1115;
    --panel: #171a21;
    --text: #e8ecf1;
    --muted: #8b93a1;
    --accent: #4ade80;
    --border: #262b35;
  }

  * { box-sizing: border-box; }

  html, body { height: 100%; margin: 0; }

  body {
    display: grid;
    place-items: center;
    padding: 24px;
    background: radial-gradient(circle at 50% 0%, #1b2030, var(--bg) 60%);
    color: var(--text);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  }

  .stopwatch {
    min-width: min(90vw, 420px);
    padding: 32px 36px 24px;
    text-align: center;
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 20px;
    box-shadow: 0 24px 60px rgba(0, 0, 0, .5);
  }

  .display {
    margin-bottom: 28px;
    font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    font-variant-numeric: tabular-nums;
    font-size: clamp(38px, 11vw, 64px);
    font-weight: 600;
    line-height: 1.1;
    letter-spacing: .02em;
    color: var(--text);
    text-shadow: 0 0 24px rgba(74, 222, 128, .12);
    transition: color .2s ease;
  }

  .display.running { color: var(--accent); }

  .buttons {
    display: flex;
    gap: 12px;
    justify-content: center;
  }

  button {
    min-width: 120px;
    padding: 12px 28px;
    font: inherit;
    font-size: 16px;
    font-weight: 600;
    color: var(--text);
    background: #202531;
    border: 1px solid var(--border);
    border-radius: 12px;
    cursor: pointer;
    transition: background .15s ease, transform .06s ease, border-color .15s ease;
  }

  button:hover { background: #262c3a; }
  button:active { transform: translateY(1px); }
  button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

  #startPause {
    color: #06210f;
    background: var(--accent);
    border-color: transparent;
  }
  #startPause:hover { background: #6ee7a0; }

  #startPause.running {
    color: #2a1a00;
    background: #fbbf24;
  }
  #startPause.running:hover { background: #fcd34d; }

  .hint {
    margin: 20px 0 0;
    font-size: 12.5px;
    letter-spacing: .02em;
    color: var(--muted);
  }

  kbd {
    padding: 1px 6px;
    font-family: inherit;
    font-size: 11.5px;
    color: var(--text);
    background: #202531;
    border: 1px solid var(--border);
    border-bottom-width: 2px;
    border-radius: 5px;
  }
</style>
</head>
<body>

  <main class="stopwatch">
    <div class="display" id="display" role="timer" aria-live="off">00:00.000</div>

    <div class="buttons">
      <button id="startPause" type="button">Start</button>
      <button id="reset" type="button">Reset</button>
    </div>

    <p class="hint"><kbd>Space</kbd> start / pause &nbsp;·&nbsp; <kbd>R</kbd> reset</p>
  </main>

<script>
(() => {
  "use strict";

  const display       = document.getElementById("display");
  const startPauseBtn = document.getElementById("startPause");
  const resetBtn      = document.getElementById("reset");

  // ---- State ------------------------------------------------------------
  // Elapsed time is always derived from timestamps, never accumulated by
  // counting ticks. A delayed or dropped frame therefore cannot cause drift.
  let running     = false;  // is the clock currently counting?
  let startStamp  = 0;      // performance.now() at the moment we (re)started
  let bankedMs    = 0;      // elapsed ms from all previous run segments
  let rafId       = null;

  const now = () => performance.now();

  /** Total elapsed milliseconds, computed fresh from the clock. */
  function elapsedMs() {
    return bankedMs + (running ? now() - startStamp : 0);
  }

  /** Format ms as [H:]MM:SS.mmm */
  function format(ms) {
    const total   = Math.max(0, Math.floor(ms));
    const hours   = Math.floor(total / 3_600_000);
    const minutes = Math.floor(total / 60_000) % 60;
    const seconds = Math.floor(total / 1_000) % 60;
    const millis  = total % 1_000;

    const pad = (n, len = 2) => String(n).padStart(len, "0");
    const base = `${pad(minutes)}:${pad(seconds)}.${pad(millis, 3)}`;

    return hours > 0 ? `${hours}:${base}` : base;
  }

  // ---- Rendering --------------------------------------------------------
  function render() {
    display.textContent = format(elapsedMs());
  }

  function tick() {
    render();
    if (running) rafId = requestAnimationFrame(tick);
  }

  // ---- Controls ---------------------------------------------------------
  function start() {
    if (running) return;
    running    = true;
    startStamp = now();          // anchor to the real clock
    startPauseBtn.textContent = "Pause";
    startPauseBtn.classList.add("running");
    display.classList.add("running");
    rafId = requestAnimationFrame(tick);
  }

  function pause() {
    if (!running) return;
    bankedMs += now() - startStamp;  // freeze the exact elapsed amount
    running   = false;
    cancelAnimationFrame(rafId);
    rafId = null;
    startPauseBtn.textContent = "Start";
    startPauseBtn.classList.remove("running");
    display.classList.remove("running");
    render();                        // show the exact frozen value
  }

  function reset() {
    running   = false;
    bankedMs  = 0;
    startStamp = 0;
    cancelAnimationFrame(rafId);
    rafId = null;
    startPauseBtn.textContent = "Start";
    startPauseBtn.classList.remove("running");
    display.classList.remove("running");
    render();
  }

  const toggle = () => (running ? pause() : start());

  // ---- Wiring -----------------------------------------------------------
  startPauseBtn.addEventListener("click", toggle);
  resetBtn.addEventListener("click", reset);

  document.addEventListener("keydown", (e) => {
    if (e.repeat || e.altKey || e.ctrlKey || e.metaKey) return;

    if (e.code === "Space") {
      e.preventDefault();   // also stops Space from "clicking" a focused button
      toggle();
    } else if (e.key === "r" || e.key === "R") {
      e.preventDefault();
      reset();
    }
  });

  // rAF is throttled in background tabs; repaint immediately on return.
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) render();
  });

  render(); // initial 00:00.000
})();
</script>
</body>
</html>
```
### Stopwatch Mechanics & Interaction

The stopwatch keeps time by recording timestamps with `performance.now()` instead of counting animation frames, so delayed callbacks won't cause drift. Here's how the pieces fit together:

- **Start / Pause toggle** – The main button switches between starting and pausing. When paused, the elapsed time is frozen and displayed exactly.
- **Reset** – Clears all banked time and returns the display to `00:00.000`.
- **Keyboard shortcuts** – Press `Space` to start or pause, and `R` to reset. The page prevents the spacebar from accidentally triggering a focused button.
- **Live display** – The timer updates every animation frame while running, showing hours only when needed, with millisecond precision.
- **Background tab handling** – When you return to the tab, the display refreshes immediately so the time stays correct.
---

**Optimization Tip:** You can adjust the millisecond display precision by changing the `pad(millis, 3)` call in the `format` function — for example, use `2` to show hundredths instead of thousandths.

